# -*- coding: utf-8 -*-
import io, json

p = 'data/.tmp/figdata_fill2a.json'
d = json.load(io.open(p, encoding='utf-8'))
byid = {x['id']: x for x in d}

def setf(fid, key, val):
    byid[fid][key] = val

setf('fig-liu-bei', 'bio', u'刘备是涿郡涿县人，汉景帝子中山靖王刘胜之后。其先织席贩履为业，家贫。早年与关羽、张飞结为兄弟。灵帝末中山郡大商张世平、苏双等赀累千金，贩马周旋于涿郡，见而异之，乃多与之金财。中平元年（184年）黄巾起义，招募义兵讨董卓。董卓迁都长安，备率众从校尉邹靖讨黄巾于下曲阳，斩首万余级。兴平元年（194年）代曹操领徐州牧，后被吕布袭夺，寄寓于袁绍。建安元年（196年）复领徐州，后又失之，遂依刘表，屯新野。建安三年（198年）与曹操战于濮阳，为曹操所败，此后依附荆州刘表。建安十二年（207年）三顾茅庐，隆中对定三分之计，得诸葛亮为谋士。是年曹操南征，备奔夏口，诸葛亮与周瑜共谋，孙刘联军在赤壁大破曹军。建安十五年（210年）备入成都，使诸葛亮、张飞等留镇荆州，自率主力西进，同年取得益州。建安十九年（214年）围成都，庞统死于落凤坡，刘璋降，益州遂定。建安二十四年（219年）汉中定，刘备进位汉中王。章武元年（221年）四月，备即皇帝位于成都，是为汉昭烈帝，国号仍称汉。次年乘吴曹相攻，出兵伐吴，夷陵之战被陆逊大败。章武三年（223年）败回白帝城，托孤于诸葛亮，曰「君可自取」。同年崩于永安宫，年六十三。')

setf('fig-zhuge-liang', 'bio', u'诸葛亮是琅邪阳都人，汉末避乱荆州。建安十二年（207年）刘备三顾草庐，诸葛亮出山，献隆中对：先取荆州为家，次取益州为基，天下有变则命一上将将荆州之军以向宛洛，将军身率益州之众出于秦川，民殷国富而不知战，并吞天下。赤壁之战中出使孙权共结盟约。刘备入蜀后，诸葛亮与关羽、张飞等留镇荆州，刘备西进，诸葛亮随之入蜀，助刘备定益州。章武元年（221年）刘备称帝，诸葛亮为丞相、录尚书事，假节。蜀汉建兴元年（223年）刘备卒，诸葛亮辅佐后主刘禅，丞相府开府治事，以身许国。为兴复汉室而兴兵北伐：建兴六年（228年）出祁山，街亭败于马谡，亮自贬三等；后出祁山六次，其中234年与司马懿相持于渭南五丈原，随军屯田，用兵不烦，与司马懿相持百余日。234年秋，亮病卒于军中，年五十四。临终上表曰「臣本布衣，躬耕于南阳，苟全性命于乱世，不求闻达于诸侯」，并言「鞠躬尽瘁，死而后已」。亮治蜀期间，改进蜀锦、发明木牛流马、改进连弩，攻心为上，治国以法，整顿吏治，南方平定。')

setf('fig-jiang-wei', 'bio', u'姜维是天水冀县人，字伯约。其母为冀县令姜氏之女，父名济，祖籍天水。少孤，与母居，处境贫困，好学不倦，立志功名。建兴六年（228年），诸葛亮出祁山，姜维时为天水郡马谡的参军，直言马谡不宜守街亭，马谡不从，街亭果然失守。诸葛亮大军退回，蜀军六镇共退兵，而姜维所在部队为邵句所置，非其本意，诸葛亮便拔姜维归汉，任为郎，授兵众。姜维自此感恩，随诸葛亮北伐，建兴九年（231年）诸葛亮出祁山，姜维为凉州刺史。诸葛亮死后，姜维迁为大将军，领凉州刺史，与大将军费祎共录尚书事。姜维屡次北伐，洮西之战大败魏将王经，段谷之战失利。姜维好立功名，胆大心细，曾献计欲图诸葛诞，意图联吴干扰魏，因泄密而还。此后钟会、邓艾伐蜀，诸葛绪被邓艾收降，姜维自沓中夜遁至剑阁，与诸葛绪合兵阻钟会于骆谷。钟会既破剑阁，诸葛绪降，维失去倚仗，被迫降于钟会，与钟会合兵进攻成都。后维与钟会密谋图蜀，引兵先趋成都，谋泄，维与诸将谋降于魏将士刘禅，不成，魏军攻维，郤正降，劝维降，维曰「我计不成，乃天命也」，遂杀郤正，纵马冲阵，终为乱兵所杀，享年六十二。')

setf('fig-zhang-yue', 'bio', u'张嶷是巴西阆中人，字伯国。早年随刘璋，后归刘备，益州平定后拜广汉太守。建兴二年（224年），诸葛亮出祁山，嶷与杨武同为巴西太守，各将兵千人，嶷送王平于柘口，驱突骑于前，张嶷率杨武等四千余人，溯流白水，相与缀行，追讨于宕渠郡界。建兴三年南征，嶷参与平定南中。建兴六年（228年），诸葛亮出祁山，嶷与魏延、吴班等随征，破曹休于武功。延熙年间，嶷累迁镇军大将军。延熙六年，诸葛亮卒，嶷为梁州刺史。延熙十三年（250年），越巂郡叟夷首领反弹，嶷率军平定，因功迁车骑将军。景耀年间，官至司徒。延熙末年，嶷与大将军姜维共录尚书事，为大将军司马。蜀汉亡后，张嶷降晋，被授为辅国将军，迁车骑将军、冀州刺史，封蒲侯。')

setf('fig-deng-ai', 's', u'魏国名将，偷渡阴平直取成都，灭亡蜀汉，后因钟会诬陷而被诬谋反，一门十余口被杀。')
setf('fig-deng-ai', 'bio', u'邓艾是义阳棘阳人，字士载，早年名字与同乡郑玄之孙郑同字，后改名为艾。少孤，与母居，养无师傅。邓艾识文断字，长于军事谋略。初为农民养鸭，十二岁移居颍川，为县吏所疑，以口吃故不为吏。后遇司马懿，懿闻名其才，召为属士，与钟会俱南征。以灭蜀之功邓艾在后期受重用，兼征西将军，后封西乡侯，邑万户。景元三年（262年）邓艾奉命与钟会并进灭蜀。钟会率主力自斜谷入蜀，邓艾则自阴平景谷道行无人之地七百余里，出江油、绵竹。邓艾行至绵竹受阻，守将诸葛瞻与黄崇先后战死，艾进军雒县，刘禅降，艾承制拜右将军，与姜维合兵涪，停田其营，旋返成都。晋武帝征艾为太尉，进爵公。钟会伐蜀后与姜维密谋据蜀自立，诬告邓艾「章摩、文王，表谋逆」，艾父子为卫瓘所追捕，缚以槛车，途中收捕诸孙及亲属，晨押至武昌，艾与诸子及孙俱坐。艾在押送途中作表与晋武帝申诉，言其志节，司马炎览表迟疑不决。诏书至，艾即自缚赴都，士众妻子皆与之同行。艾见军令不轨、矫诏行事，怒曰「艾所保者王也，此自欺也」，乃拒绝辩解。卫瓘派一行人将艾父子等追于绵竹江上，斩艾及诸子于江中，艾一家十余口被杀。')

setf('fig-zhuge-shang', 'bio', u'诸葛瞻是诸葛亮之子，字思远。少时聪敏过人，身长八尺，仪表甚伟。诸葛亮平定南中后，瞻随父在汉中，十七岁那年，诸葛亮第一次北伐时，瞻尚为不入仕之童，步行来见诸葛亮，诸葛亮当时年幼，却十分看重他，说「非熊罴之士」之语，勉励他。蜀汉建兴十二年（234年）诸葛亮卒，瞻升为中庶子，为后主刘禅的贴身将领，辅佐太子。历任军师将军、尚书、忠武将军。景耀三年（260年），蜀汉内部宦官黄皓专权，瞻上表后主斥其奸，请分割其权，疏未上达。魏国果然因此发动进攻。炎兴元年（263年），魏将邓艾偷渡阴平，诸葛瞻率诸军拒之于绵竹，与魏将黄崇战于绵竹南，斩黄崇。后退至竹马，兵溃，瞻与诸子诸葛尚、诸葛黄俱战死于阵中，一门七人皆死，年三十五。诸葛瞻死后，其子诸葛尚亦死。后主下诏褒扬，追赠瞻为武侯，祠于绵竹。诸葛瞻不配食于宗庙，其母尚氏为其辞曰「夫臣子之义，不贰国」。')

setf('fig-chen-qun', 'bio', u'陈群是颍川鄢陵人，其祖父陈寔为汉太丘长，其父陈纪为荀彧所拔的「八龙」之一。陈群早孤，贫而不媚，祖父陈寔异之。祖父亡时，陈群年幼，随长兄陈谌往养亲属，避乱江东。族叔陈球为太尉，陈群往谒之，球曰：「卿是荀君同类，何不先入言？」群即起，未及陈球坐，群曰：「昔有豫让为智伯报仇，漆身为厉，吞炭为哑，今日之事，犹是而已。」球大奇之。汉末陈群避乱淮南，曾劝袁术称帝不成，携族属渡江投刘表，表辟为从事，后与刘备论人物，刘备问「臧君高视万物」，先主亦以卿为方之 man 属。汉末陈群避乱淮南，曾劝袁术称帝不成。曹丕即位，征陈群为御史中丞，转为尚书。曹丕称帝后，与尚书令陈群议九品官人之法，规定在郡县设中正，考察士人才能、家世而分九等，作为朝廷选拔官吏的依据。陈群又建议定律、改进法制、改进服饰车舆冠冕等制度，为曹魏的制度奠基。其后历任尚书、司空、司徒、录尚书事，为曹魏重臣。太和元年（227年）率群臣劝曹丕称帝，帝曰「此事固宜即时行也」，群遂议。曹叡即位后，陈群与曹真、王朗等并受遗诏辅政，官至司空。景初元年（237年）去世，追赠谥曰敬侯。')

setf('fig-gongsun-yuan', 'bio', u'公孙渊是襄平人，公孙康之子，东燕国君主。父公孙康与曹魏交好，其父死，渊继位。太和六年（232年），渊因司马懿与东吴交战、辽东空虚，率步骑数万袭击魏玄菟郡，斩杀偏将军赵汝，攻破诸县，返回后自称燕王，改元天授。魏明帝遣毌丘俭等讨之，俭至辽东，烽燧相举，兵退还。渊又与吴国孙权通使往来，权遣使拜渊为燕王。司马懿上疏请讨渊，帝乃命懿率步骑四万南征，辽东诸县官民皆降。懿至襄平，渊遣将卑衍、杨祚等步骑数万屯于辽隧，围堑二十余里。懿与诸将谋曰「贼坚营高，非攻之所能破也」，乃多张旗帜，欲出其南，潜以舟载兵入渭水堰，以水军攻其营。渊放牧马以阻战，懿使兵斫其马枥，渊惊而引去，懿等济水，斩首数千级，追至襄平。渊自请为降，说「大魏国士，远来相救，所求无厌，孤恐开门相待，必见禽讨，不如以死相拒」。遂夜遁走，为魏军追及于梁水之上，渊众大散，兄弟五人皆被斩，渊为部将徐德所斩，首级献于洛阳。')

setf('fig-yu-jin', 'bio', u'于禁是泰山巨平人，字文则，早年从曹操起兵，是曹操麾下最资深的将领之一，建安元年为裨将军，与张绣战于宛城失利后，独与本部击破青州兵，因功迁中郎将。建安三年为建忠将军，封关内侯，与张辽、乐进、张郃、徐晃同为五子良将。建安十年，黑山贼张燕降而复叛，禁与张辽奉命追击，斩首万余级，迁为雍州刺史。建安十三年赤壁之战后，与张辽屯合肥，为刘备所败。建安二十四年（219年）刘备围樊城，曹操征于禁去救，禁与庞德大破刘备军，斩严颜，平陈兰、梅成等，退兵时为刘备所袭，大败，庞德被斩，禁与麾下数十骑被围，乏食，凿堑而守。关羽乘船临城，禁等穷迫，遂降羽。曹操闻禁降，怒曰「吾知禁三十年，何意临危处难，反不如剧孟」。后孙权复叛，曹操南下击败孙权而还，闻禁等在吴，敕禁归，禁至，拜属国相见而泣曰「诸君不知禁，何以至今」。后世以禁为降将失节之戒，丕立庙于洛阳，谥曰壮侯，禁子孙皆列于将相之林。')

setf('fig-cao-huang', 'bio', u'曹奂是曹魏第二代皇帝曹睿的养孙，曹宇之子，字彦士。甘露五年（260年）高贵乡公曹髦在司马昭控制下被杀，景元元年（260年）立曹奂为帝，改元景初。曹奂即位时年仅十四岁，完全受制于司马氏：嘉平元年（249年）高平陵之变时他已即位，事后改元正始，此后正始年间司马懿专政，废高贵乡公曹芳而立他。曹爽、司马师先后掌权，曹奂几为傀儡。司马师废曹芳时，曹奂虽在旁而不敢作声。咸熙元年（264年）司马昭受相国、晋公之号，掌握魏国军政大权，魏国已是司马氏天下。咸熙二年（265年）司马炎受魏元帝曹奂禅让，建立西晋，改元泰始，曹魏灭亡，曹奂封晋帝，为山阳公。太安年间东海王司马越专权，晋惠帝皇后羊氏诬陷曹奂谋反，司马越使司马欣带兵讨之，公元300年曹奂被废为河阳王，后被改封安平公，公元302年死，年五十七，谥景王。')

setf('fig-han-emperor-mingdi', 's', u'西晋第二位皇帝，即位时司马氏内乱方炽，凭平定王敦之乱与重建禁军的举措获得朝野推重。')

setf('fig-liu-mao', 'bio', u'刘毅是东莱掖县人，字仲雄，西晋开国元勋。他的妹妹为晋武帝司马炎之皇后杨芷，自己则以外戚身份受重用。武帝受禅，毅拜为散骑常侍，迁尚书左仆射。武帝晚年，毅以杨皇后之助，排挤王导、谢安等元勋，主张罢免王导录尚书事，以加强皇权与外戚之权。泰始年间大司马王敦辅政，敦与刘毅、羊祜等不协。咸宁四年（278年）武帝临终，禁中诸人受遗诏辅政，疑刘毅与刘宝等欲易诏，遣使收刘毅。刘毅奔于遵，为追兵所获，遇害于车中。建兴四年（316年）晋室南渡后，其后人在东晋一代仍颇显赫，其家族影响延续东晋。')

setf('fig-liu-yao', 's', u'西晋将领，元勋之后，镇守荆州牵制王敦，永嘉之乱前病卒于武昌。')
setf('fig-liu-yao', 'bio', u'刘瑶是东莱人，晋武帝的外戚，其妹为司马炎元配杨氏之族。刘瑶少时好学，招纳人才，其客常数十人。太康初，迁步兵校尉、右卫将军，宿卫禁中。与王敦交厚，深得王敦信任。永嘉元年（307年），刘瑶受命为征南将军、都督江州荆豫益梁雍六州诸军事、假节，镇武昌，以北伐为务。他经营江汉，缮甲兵，积谷食，兵以众强为称。永嘉五年（311年）洛阳陷落，晋怀帝被虏，晋室南渡，王敦以刘瑶为征西大将军，都督江州牧，瑶不受命。王敦之乱平后，明帝以刘瑶为征南将军。刘瑶晚年病卒于武昌，赠车骑将军，谥曰肃王。')

setf('fig-sima-de', 'bio', u'司马德是河内温县人，司马懿之孙、司马伷之子、晋明帝司马绍的堂兄弟，东晋宗室。司马德袭封鄄陵县公，历任抚军将军、车骑将军。建元九年（321年），王敦之乱平定后，司马德入朝任散骑常侍，后拜抚军将军。太宁三年（322年）以左卫将军、录尚书参辅朝政。明帝即位，拜右卫将军，与王导等并受顾命。苏峻之乱时，司马德与右卫将军庾亮、司州刺史温峤共赴京师，峻使兵攻之，德不能御，弃军奔白石，庾亮战于石头，峻攻陷建康，司马德与温峤等赴会稽，收集散兵，起兵讨峻。明帝以司马德为大都督，帅师讨峻，破其众，峻死。苏峻之乱平后，司马德以功拜骠骑将军，都督中外诸军事，镇石头城。太和二年（326年）代庾亮为都督江荆豫益梁雍六州军事，都督江州，后为征西将军。咸和五年（329年）后石勒侵掠河南，司马德退镇武昌，咸和六年（331年）后疾笃，卒于京邑。其子司马曜、司马超先后镇守荆州。')

setf('fig-sima-jiong', 'bio', u'司马冏是河内温县人，晋武帝司马炎之侄，司马颖之弟，封安平王。永康元年（307年），赵王司马颖改立皇太弟，以冏为皇太弟，居戚里。朝士恶其窃位，多有归附成都王颖者。司马颖与河间王颙、长沙王乂争夺皇位，冏起兵讨成都王颖，斩其将乂于乐池，颙等退。永嘉元年（307年）在朝廷支持下，冏与东海王越等共起兵讨成都王颖，成都王颖在皇城被杀，冏因此拜丞相、都督中外诸军事，录尚书事，河北刺史。永嘉元年，司马越从下邳起兵讨冏，冏遣将司马郭给他的军队击败司马越，两军相持于洛阳城下。永嘉元年（307年）司马越入洛阳，冏出奔，被捕，后被杀于金墉城，终年三十六。冏被诸王讨灭后，其弟司马颖被立为皇太弟，成都王颖则被东海王越击败逃亡。')

setf('fig-sima-ying', 'bio', u'司马颖是河内温县人，晋武帝之子，司马伦之弟，封成都王。永嘉元年（307年）成都王颖与河间王颙、长沙王乂为争夺皇位互相攻伐，司马颖被立为皇太弟，迁于邺城，拜丞相、都督中外诸军事，录尚书事，假黄钺，河北诸州皆为其统属。他大赦天下，改爵为成都王，食邑万户。颖颇顿兵不进，欲观成败，自失河北，众皆恨之。东海王越与王浚等率军讨伐，颖遣石超率五万人讨之，屡败。越遂入洛阳，惠帝出奔，投奔邺城之颖。颖拜越为大司马，加殊礼。颖自为皇太弟后，立其子为皇太子，幽囚皇太子司马颖。永嘉二年（308年），司马越复率众讨颖，颖败走，途中被张方部下捕获，被迫食饼屑，惭愤吐血而死，年三十一。')

setf('fig-sima-yue', 'bio', u'司马岳是河内温县人，晋武帝之子，宣帝司马懿之孙，琅邪恭王司马伷之子，封为安平王，与赵王司马颖、汝南王司马亮等为兄弟。太安元年（306年），颖、颙、乂举兵，八王之乱大起。司马岳参与诸王讨伐成都王颖的军事行动。永嘉元年（307年），与东海王司马越等合兵，击败河间王颙部将张艾于河南，斩张艾首。永嘉二年（308年），司马越再度起兵讨司马伦与司马颖，司马岳与诸王合军，破伦于荡阴之役，伦被杀。晋惠帝复位后，司马岳受封为南阳王，邑万户，拜抚军将军，参与辅政。此后在东海王越讨成都王颖的战役中，司马岳在军中有功。永嘉之乱后，司马岳随晋室南渡，镇守地方，为琅邪王司马睿在江南建立东晋的重要支持者之一。')

setf('fig-liuyuan', 'bio', u'刘渊是匈奴屠各部人，姓刘，名渊，字元海，其母是呼延氏。刘渊七岁丧母，太傅呼延攸抚养教导，与汝阴太守刘焕交好。刘渊幼时好学，异母兄刘呼延攸、姨母之子刘渊双皆奇其才。晋时刘渊为北部都尉，左部帅。刘渊曾与王浚、司马颖等图谋举兵，因事泄，王浚坐贾后被诛，呼延攸劝刘渊先避于上党，保全门户口。刘渊居于太原。永兴元年（304年）在离石起兵，南下称汉王，都离石。永兴二年迁都平阳，改称汉昭帝，改元永兴。刘聪在位期间灭西晋、掳晋怀帝，刘渊最终未能完成统一，死后由其子刘聪继位。刘渊在位六年，公元310年卒，谥曰光文帝，庙号高祖。汉赵是十六国中第一个由内迁羯族之外建立的政权，标志着五胡十六国时代的开始。')

setf('fig-li-yun', 'bio', u'李云是北魏将领、尚书，北魏孝文帝时的重要大臣。他早年随军北征柔然，屡建功勋。太和年间，孝文帝推行汉化，李云以将军、尚书之职参与其中，被派往北方安抚诸部，宣喻孝文帝的德意。孝文帝为解决六镇军户与鲜卑贵族矛盾，自将六镇之民迁于中原，诈称新制，李云奉命宣诏于诸镇，六镇之民既闻新制，惧其残暴，聚众而反，六镇之乱起。李云随李冲等参与平叛，叛军退据怀朔，李云与将追击，斩其帅，破其众。李云以功进爵彭城公。孝文帝南征时，李云与李冲、拓跋丕等参与谋划迁都洛阳之议，主张从汉制、禁胡服、断北语、一夫一妇的婚丧之礼，以革鲜卑旧俗。李云后拜尚书令，寝疾，赐爵长平公。')

setf('fig-yang-jian', 'bio', u'杨坚是弘农华阴人，杨忠之子，出身关陇军事贵族集团。其父杨忠早年随宇文泰入关，位居八柱国之一，赐姓宇文氏，号大隋国公。杨坚继承家业，历任北周大丞相、隋国公，长期辅佐宇文氏政权。北周静帝宇文阐即位后，杨坚以大丞相身份掌握朝政，其女杨丽华被立为皇后，后周宣帝宇文赟即位，杨坚为上柱国、大司马。宣帝死后，静帝年幼，杨坚以欺幼弱、专擅之罪被贬为上柱国、邓国公，随即于大象二年（580年）进位相国、隋国公，加九锡。同年宇文阐禅位于杨坚，北周灭亡，与北齐分裂的局面告终。杨坚即隋文帝，定都长安，改革官制、颁行《开皇律》，其后统一全国。杨坚与独孤伽罗后及其家族共同构成隋代皇室的统治核心，其子杨广后来继位。')

setf(u'fig-\u5c14\u6731\u8363', 'bio', u'尔朱荣是契胡人，祖先为契胡别部酋长。尔朱荣早年随父尔朱兆征战，逐渐成为部落中势力最强者。北魏孝明帝时期，尔朱荣与权臣刘腾、高贵乡公等对立，隆昌元年（512年）尔朱荣起兵，攻破河内，擒刘腾于青州，孝明帝派人慰谕。孝明帝暴崩后，尔朱荣进兵洛阳，立孝庄帝拓跋子攸，是为尔朱荣掌权之始。尔朱荣性骄暴，滥杀朝士及宗室，河北豪强、世家大族多遭残害，人心惶惶。天平元年（530年）尔朱荣与葛荣部将高欢等起兵攻破洛阳，尔朱荣沉太后与幼主于河，残忍无道。此举激起河北军民反抗，南、北分裂。天平二年（531年）高欢起兵讨尔朱荣，尔朱荣兵败被擒，为晋州刺史刘显所斩，首级献于大同。尔朱荣之死，使尔朱氏势力迅速瓦解，为高欢、宇文泰两大势力分立天下奠定基础。')

setf('fig-liu-xie', 'bio', u'刘勰是东莞莒人，字德龙。刘勰自幼孤贫，寄养于僧寺，读书不倦。夜梦一美妇人告之曰「有文在焉，宜取之」，自是梦中常诵奇书。及长，为舅之外亲，乞养定礼，撰《礼记正论》二十篇。刘勰后奉敕为梁武帝撰写《文心雕龙》，凡十卷，五十篇，分上下部。上部论文体与创作原理，标举《原道》《宗经》《正纬》《辨骚》《明诗》《神思》等篇；下部自《时序》以下，论批评与文体流别，兼叙古代文学发展，末篇《序志》自述著书缘起与体例，为中国文学批评史上第一部品评作家与作品的专书。刘勰在书中提出「原道」「宗经」「文质并重」「知音」等命题，对后世文学理论影响深远。刘勰晚年随僧人慧远依居庐山，曾奉敕撰定佛经序，隋文帝时其书传入日本，影响唐代。梁武帝晚年，刘勰出为宁远将军，记室，迁军咨祭酒。晚年贫病交集而卒。据传其墓在山东莒县，碑文刻「文心雕龙」四字。')

